package sqlite

// schema defines the only supported storage format. No migrations are applied.
const schema = `CREATE TABLE administrators(id INTEGER PRIMARY KEY CHECK(id=1),username TEXT NOT NULL,password_hash BLOB NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,administrator_id INTEGER NOT NULL REFERENCES administrators(id),expires_at INTEGER NOT NULL);
CREATE TABLE tmdb_cache(key TEXT PRIMARY KEY,value BLOB NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE rule_chain(id TEXT PRIMARY KEY CHECK(id='current'));
CREATE TABLE config(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE CHECK(id='1'),f_version INTEGER NOT NULL,f_source_root TEXT NOT NULL,f_target_root TEXT NOT NULL,f_token TEXT NOT NULL,f_proxy_url TEXT NOT NULL,f_language TEXT NOT NULL,f_rules_movie_folder TEXT NOT NULL,f_rules_movie_file TEXT NOT NULL,f_rules_tv_folder TEXT NOT NULL,f_rules_tv_file TEXT NOT NULL);
CREATE TABLE config_categories(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_name TEXT NOT NULL,f_type TEXT NOT NULL,f_year_min INTEGER NOT NULL,f_year_max INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES config(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES config(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX config_categories_root ON config_categories(root);
CREATE TABLE category_countries(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES config_categories(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES config(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX category_countries_root ON category_countries(root);
CREATE TABLE category_genres(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES config_categories(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES config(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX category_genres_root ON category_genres(root);
CREATE TABLE rules(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_id TEXT NOT NULL,f_name TEXT NOT NULL,f_description TEXT NOT NULL,f_target TEXT NOT NULL,f_source TEXT NOT NULL,f_order INTEGER NOT NULL,f_enabled INTEGER NOT NULL,f_kind TEXT NOT NULL,f_stage TEXT NOT NULL,f_config_code TEXT NOT NULL,f_config_params TEXT,f_config_pattern TEXT NOT NULL,f_config_capture TEXT NOT NULL,f_config_value TEXT,FOREIGN KEY(owner) REFERENCES rule_chain(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES rule_chain(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX rules_root ON rules(root);
CREATE TABLE rule_examples(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_root TEXT NOT NULL,f_expected TEXT,FOREIGN KEY(owner) REFERENCES rules(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES rule_chain(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE TABLE rule_examples_paths(owner TEXT NOT NULL REFERENCES rule_examples(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,PRIMARY KEY(owner,position));
CREATE TABLE rule_examples_targets(owner TEXT NOT NULL REFERENCES rule_examples(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,PRIMARY KEY(owner,position));
CREATE INDEX rule_examples_root ON rule_examples(root);
CREATE TABLE recognitions(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,f_revision INTEGER NOT NULL,f_state TEXT NOT NULL,f_completed INTEGER NOT NULL,f_total INTEGER NOT NULL,f_error TEXT NOT NULL,f_created TEXT NOT NULL);
CREATE TABLE workspace_paths(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES recognitions(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX workspace_paths_root ON workspace_paths(root);
CREATE TABLE workspace_items(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_path TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL,f_season INTEGER NOT NULL,f_group TEXT NOT NULL,f_state TEXT NOT NULL,f_reason TEXT NOT NULL,f_selected INTEGER NOT NULL,f_removed INTEGER NOT NULL,f_edited INTEGER NOT NULL,f_trace_id TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES recognitions(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX workspace_items_root ON workspace_items(root);
CREATE TABLE item_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES workspace_items(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_episodes_root ON item_episodes(root);
CREATE TABLE metadata_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES item_metadata(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX metadata_episodes_root ON metadata_episodes(root);
CREATE TABLE trace_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES trace_metadata(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX trace_episodes_root ON trace_episodes(root);
CREATE TABLE mapping_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES media_mappings(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES media_mappings(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX mapping_episodes_root ON mapping_episodes(root);
CREATE TABLE run_mapping_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES run_mappings(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES runs(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX run_mapping_episodes_root ON run_mapping_episodes(root);
CREATE TABLE item_metadata(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position=0),f_tmdbid INTEGER,f_title TEXT,f_media_type TEXT,f_year INTEGER,f_season INTEGER,f_release_tag TEXT,FOREIGN KEY(owner) REFERENCES workspace_items(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_metadata_root ON item_metadata(root);
CREATE TABLE trace_metadata(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position=0),f_tmdbid INTEGER,f_title TEXT,f_media_type TEXT,f_year INTEGER,f_season INTEGER,f_release_tag TEXT,FOREIGN KEY(owner) REFERENCES extraction_traces(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX trace_metadata_root ON trace_metadata(root);
CREATE TABLE item_entries(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position=0),f_tmdbid INTEGER NOT NULL,f_type TEXT NOT NULL,f_title TEXT NOT NULL,f_original_title TEXT NOT NULL,f_year INTEGER NOT NULL,f_overview TEXT NOT NULL,f_date TEXT NOT NULL,f_poster_path TEXT NOT NULL,f_backdrop_path TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES workspace_items(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_entries_root ON item_entries(root);
CREATE TABLE item_entries_genres(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES item_entries(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_entries_genres_root ON item_entries_genres(root);
CREATE TABLE item_entries_countries(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES item_entries(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_entries_countries_root ON item_entries_countries(root);
CREATE TABLE item_entries_cast(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_name TEXT NOT NULL,f_role TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES item_entries(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_entries_cast_root ON item_entries_cast(root);
CREATE TABLE item_candidates(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_tmdbid INTEGER NOT NULL,f_type TEXT NOT NULL,f_title TEXT NOT NULL,f_original_title TEXT NOT NULL,f_year INTEGER NOT NULL,f_overview TEXT NOT NULL,f_date TEXT NOT NULL,f_poster_path TEXT NOT NULL,f_backdrop_path TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES workspace_items(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_candidates_root ON item_candidates(root);
CREATE TABLE item_candidates_genres(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES item_candidates(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_candidates_genres_root ON item_candidates_genres(root);
CREATE TABLE item_candidates_countries(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES item_candidates(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_candidates_countries_root ON item_candidates_countries(root);
CREATE TABLE item_candidates_cast(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_name TEXT NOT NULL,f_role TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES item_candidates(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_candidates_cast_root ON item_candidates_cast(root);
CREATE TABLE runs(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,f_title TEXT NOT NULL,f_mode TEXT NOT NULL,f_state TEXT NOT NULL,f_created TEXT NOT NULL,f_error TEXT NOT NULL,f_completed INTEGER NOT NULL,f_total INTEGER NOT NULL,f_undo INTEGER NOT NULL,f_batch_id TEXT NOT NULL,f_version INTEGER NOT NULL,f_recognition_id TEXT NOT NULL,f_purpose TEXT NOT NULL);
CREATE TABLE run_mappings(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_path TEXT NOT NULL,f_run_id TEXT NOT NULL,f_source TEXT NOT NULL,f_type TEXT NOT NULL,f_tmdbid INTEGER NOT NULL,f_season INTEGER NOT NULL,f_state TEXT NOT NULL,f_identity TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES runs(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES runs(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX run_mappings_root ON run_mappings(root);
CREATE TABLE media_mappings(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,f_path TEXT NOT NULL,f_run_id TEXT NOT NULL,f_source TEXT NOT NULL,f_type TEXT NOT NULL,f_tmdbid INTEGER NOT NULL,f_season INTEGER NOT NULL,f_state TEXT NOT NULL,f_identity TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL);
CREATE TABLE operations(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL,f_id INTEGER NOT NULL,f_kind TEXT NOT NULL,f_source TEXT NOT NULL,f_target TEXT NOT NULL,f_mode TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL,f_content BLOB,f_url TEXT NOT NULL,f_convert_jpeg INTEGER NOT NULL,f_status TEXT NOT NULL,f_error TEXT NOT NULL,f_hash TEXT NOT NULL,f_temp TEXT NOT NULL,f_replace_hold TEXT NOT NULL,f_remove_hold TEXT NOT NULL,f_source_remove_hold TEXT NOT NULL,f_identity TEXT NOT NULL,f_source_identity TEXT NOT NULL,f_replace INTEGER NOT NULL,f_replace_identity TEXT NOT NULL,f_replace_size INTEGER NOT NULL,f_replace_m_time INTEGER NOT NULL,f_owner TEXT NOT NULL,f_reused INTEGER NOT NULL,undo_parent TEXT REFERENCES operations(k) ON DELETE CASCADE,FOREIGN KEY(owner) REFERENCES runs(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES runs(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX operations_root ON operations(root);
CREATE TABLE operation_owners(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES operations(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES runs(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX operation_owners_root ON operation_owners(root);
CREATE TABLE extraction_traces(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,f_path TEXT NOT NULL,f_root TEXT NOT NULL,f_workspace_id TEXT NOT NULL,f_status TEXT NOT NULL,f_started_at TEXT NOT NULL,f_finished_at TEXT NOT NULL,f_error TEXT NOT NULL);
CREATE TABLE extraction_steps(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_rule_id TEXT NOT NULL,f_rule_name TEXT NOT NULL,f_order INTEGER NOT NULL,f_target TEXT NOT NULL,f_stage TEXT NOT NULL,f_file_id TEXT NOT NULL,f_status TEXT NOT NULL,f_matched_text TEXT NOT NULL,f_extracted_value TEXT,f_before TEXT,f_after TEXT,f_applied INTEGER NOT NULL,f_reason TEXT NOT NULL,f_started_at TEXT NOT NULL,f_duration_ms REAL NOT NULL,FOREIGN KEY(owner) REFERENCES extraction_traces(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX extraction_steps_root ON extraction_steps(root);
CREATE TABLE step_rules(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position=0),f_id TEXT NOT NULL,f_name TEXT NOT NULL,f_description TEXT NOT NULL,f_target TEXT NOT NULL,f_source TEXT NOT NULL,f_order INTEGER NOT NULL,f_enabled INTEGER NOT NULL,f_kind TEXT NOT NULL,f_stage TEXT NOT NULL,f_config_code TEXT NOT NULL,f_config_params TEXT,f_config_pattern TEXT NOT NULL,f_config_capture TEXT NOT NULL,f_config_value TEXT,FOREIGN KEY(owner) REFERENCES extraction_steps(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX step_rules_root ON step_rules(root);
CREATE TABLE step_rule_examples(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_root TEXT NOT NULL,f_expected TEXT,FOREIGN KEY(owner) REFERENCES step_rules(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE TABLE step_rule_examples_paths(owner TEXT NOT NULL REFERENCES step_rule_examples(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,PRIMARY KEY(owner,position));
CREATE TABLE step_rule_examples_targets(owner TEXT NOT NULL REFERENCES step_rule_examples(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,PRIMARY KEY(owner,position));
CREATE INDEX step_rule_examples_root ON step_rule_examples(root);
CREATE TABLE step_inputs(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES extraction_steps(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX step_inputs_root ON step_inputs(root);
CREATE TABLE step_captures(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_name TEXT NOT NULL,f_value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES extraction_steps(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX step_captures_root ON step_captures(root);
CREATE TABLE step_attempts(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_input TEXT NOT NULL,f_matched INTEGER NOT NULL,f_matched_text TEXT NOT NULL,f_error TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES extraction_steps(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX step_attempts_root ON step_attempts(root);
CREATE TABLE attempt_captures(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_name TEXT NOT NULL,f_value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES step_attempts(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX attempt_captures_root ON attempt_captures(root);
CREATE TABLE attempt_events(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_phase TEXT NOT NULL,f_line INTEGER NOT NULL,f_column INTEGER NOT NULL,f_function TEXT NOT NULL,f_operation TEXT NOT NULL,f_message TEXT NOT NULL,f_data TEXT,FOREIGN KEY(owner) REFERENCES step_attempts(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX attempt_events_root ON attempt_events(root);
CREATE TABLE execution_queue(position INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT NOT NULL UNIQUE REFERENCES runs(id),purpose TEXT NOT NULL CHECK(purpose IN ('organize','scrape')));
CREATE INDEX execution_queue_purpose ON execution_queue(purpose,position);
CREATE INDEX runs_purpose ON runs(f_purpose,sequence);
CREATE INDEX runs_batch ON runs(f_batch_id,sequence);
CREATE INDEX runs_state ON runs(f_state);
CREATE INDEX runs_workspace ON runs(f_recognition_id);
CREATE INDEX operations_target ON operations(f_target,f_status);
CREATE INDEX run_mappings_path ON run_mappings(f_path);
CREATE INDEX media_mappings_work ON media_mappings(f_type,f_tmdbid);
CREATE INDEX extraction_trace_workspace ON extraction_traces(f_workspace_id);
CREATE INDEX extraction_trace_path ON extraction_traces(f_path);
CREATE UNIQUE INDEX operations_undo_parent ON operations(undo_parent) WHERE undo_parent IS NOT NULL;
`
